"""Exact metadata regions are caller-approved, not generated by the exporter."""

import copy
import json
from pathlib import Path

import pytest
from wordgame_pipeline.export.p2_manifest import p2_manifest
from wordgame_pipeline.sequence.curve import CurveConfig
from wordgame_pipeline.sequence.slots import Location, Region, Reservation, SlotPlan
from wordgame_pipeline.validate.schema import SchemaRegistry

ROOT = Path(__file__).parents[2]
REGISTRY = SchemaRegistry(ROOT)


def fixture():
    base = json.loads((ROOT.parent / "game/content/pl/manifest.json").read_bytes())
    plan = SlotPlan(
        (Region("r1", CurveConfig(1, 65, 0, 0, 5, 0, 0.2, 0.1, ())),),
        (Location("l1", "r1", 1, 30), Location("l2", "r1", 31, 65)),
        tuple(Reservation(i, f"c{i}") for i in range(1, 16)),
        (),
    )
    region = {"r1": {"name_key": "journey.region.r1"}}
    locations = {
        "l1": {"name_key": "journey.location.l1", "postcard": "postcards/l1.webp", "pieces": 8},
        "l2": {"name_key": "journey.location.l2", "postcard": "postcards/l2.webp", "pieces": 8},
    }
    return base, plan, region, locations


def test_additive_manifest_does_not_touch_p1_packs_or_raw_receipt():
    base, plan, region, locations = fixture()
    before = copy.deepcopy((base, region, locations))
    result = p2_manifest(base, plan, region, locations, REGISTRY)
    assert result["packs"] == base["packs"]
    assert result["slots"] == 65
    assert result["regions"] == [
        {"id": "r1", "name_key": "journey.region.r1", "first": 1, "last": 65}
    ]
    assert [(row["id"], row["first"], row["last"]) for row in result["locations"]] == [
        ("l1", 1, 30),
        ("l2", 31, 65),
    ]
    assert result["landmarks"] == []
    assert (base, region, locations) == before
    assert p2_manifest(base, plan, region, locations, REGISTRY) == result


def test_missing_fabricated_or_invalid_metadata_rejected():
    base, plan, region, locations = fixture()
    with pytest.raises(ValueError):
        p2_manifest(base, plan, {}, locations, REGISTRY)
    with pytest.raises(ValueError):
        p2_manifest(base, plan, region, {"l1": locations["l1"]}, REGISTRY)
    wrong = copy.deepcopy(locations)
    wrong["l2"]["postcard"] = "../assets/foo"
    with pytest.raises(ValueError):
        p2_manifest(base, plan, region, wrong, REGISTRY)
    wrong = copy.deepcopy(region)
    wrong["r1"]["name_key"] = "unreviewed_region_name"
    with pytest.raises(ValueError):
        p2_manifest(base, plan, wrong, locations, REGISTRY)


def test_wrong_slot_count_or_preexisting_metadata_rejected():
    base, plan, region, locations = fixture()
    base["slots"] = 200
    with pytest.raises(ValueError):
        p2_manifest(base, plan, region, locations, REGISTRY)
    base["slots"] = 65
    base["regions"] = []
    with pytest.raises(ValueError):
        p2_manifest(base, plan, region, locations, REGISTRY)
